-- # SET GENERATED BY DEFAULT lets a value be assigned to a GENERATED ALWAYS
-- # identity column (General Rules, 2.b.ii). The rows keep their values and
-- # the sequence carries on.
CREATE TABLE foo (id INT GENERATED ALWAYS AS IDENTITY, x INT);
INSERT INTO foo (x) VALUES (1);
ALTER TABLE foo ALTER COLUMN id SET GENERATED BY DEFAULT;
INSERT INTO foo (id, x) VALUES (10, 2);
INSERT INTO foo (x) VALUES (3);
UPDATE foo SET id = 20 WHERE x = 3;
SELECT * FROM foo;
SELECT IS_IDENTITY, IDENTITY_GENERATION FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'FOO' AND COLUMN_NAME = 'ID';
-- msg: CREATE TABLE 1
-- msg: INSERT 1
-- msg: ALTER TABLE 1
-- msg: INSERT 1
-- msg: INSERT 1
-- msg: UPDATE 1
-- ID: 1 X: 1
-- ID: 10 X: 2
-- ID: 20 X: 3
-- IS_IDENTITY: YES IDENTITY_GENERATION: BY DEFAULT

-- # SET GENERATED ALWAYS means a value can't be assigned to the column
-- # (General Rules, 2.b.i). Without the optional COLUMN.
CREATE TABLE foo (id INT GENERATED BY DEFAULT AS IDENTITY, x INT);
INSERT INTO foo (id, x) VALUES (5, 1);
ALTER TABLE foo ALTER id SET GENERATED ALWAYS;
INSERT INTO foo (id, x) VALUES (6, 2);
UPDATE foo SET id = 7;
INSERT INTO foo (x) VALUES (3);
SELECT * FROM foo;
-- msg: CREATE TABLE 1
-- msg: INSERT 1
-- msg: ALTER TABLE 1
-- error 428C9: cannot assign a value other than DEFAULT to column ID, which is GENERATED ALWAYS
-- error 428C9: cannot assign a value other than DEFAULT to column ID, which is GENERATED ALWAYS
-- msg: INSERT 1
-- ID: 5 X: 1
-- ID: 1 X: 3

-- # It doesn't matter if the column is already generated that way.
CREATE TABLE foo (id INT GENERATED ALWAYS AS IDENTITY, x INT);
ALTER TABLE foo ALTER COLUMN id SET GENERATED ALWAYS;
INSERT INTO foo (x) VALUES (1);
SELECT * FROM foo;
-- msg: CREATE TABLE 1
-- msg: ALTER TABLE 1
-- msg: INSERT 1
-- ID: 1 X: 1

-- # The other options can follow it, and change the sequence (General Rules,
-- # 1).
CREATE TABLE foo (id INT GENERATED BY DEFAULT AS IDENTITY, x INT);
INSERT INTO foo (x) VALUES (1);
ALTER TABLE foo ALTER COLUMN id SET GENERATED ALWAYS SET INCREMENT BY 10 RESTART WITH 100;
INSERT INTO foo (x) VALUES (2), (3);
/* out */
/* in */
SELECT * FROM foo;
-- msg: CREATE TABLE 1
-- msg: INSERT 1
-- msg: ALTER TABLE 1
-- msg: INSERT 2
-- out: CREATE TABLE "PUBLIC"."FOO" (
-- out:   "ID" INTEGER GENERATED ALWAYS AS IDENTITY (START WITH 1 INCREMENT BY 10 MINVALUE 1 MAXVALUE 2147483647) NOT NULL,
-- out:   "X" INTEGER
-- out: );
-- out: INSERT INTO "PUBLIC"."FOO" ("ID", "X") OVERRIDING SYSTEM VALUE VALUES (1, 1);
-- out: INSERT INTO "PUBLIC"."FOO" ("ID", "X") OVERRIDING SYSTEM VALUE VALUES (100, 2);
-- out: INSERT INTO "PUBLIC"."FOO" ("ID", "X") OVERRIDING SYSTEM VALUE VALUES (110, 3);
-- out: ALTER TABLE "PUBLIC"."FOO" ALTER COLUMN "ID" RESTART WITH 120;
-- ID: 1 X: 1
-- ID: 100 X: 2
-- ID: 110 X: 3

-- # Only an identity column can be changed (11.12, Syntax Rules, 7).
CREATE TABLE foo (id INT);
ALTER TABLE foo ALTER COLUMN id SET GENERATED ALWAYS;
-- msg: CREATE TABLE 1
-- error 42601: syntax error: column ID is not an identity column

-- # A ROLLBACK brings back how it was generated.
CREATE TABLE foo (id INT GENERATED ALWAYS AS IDENTITY, x INT);
START TRANSACTION;
ALTER TABLE foo ALTER COLUMN id SET GENERATED BY DEFAULT;
ROLLBACK;
INSERT INTO foo (id, x) VALUES (6, 1);
-- msg: CREATE TABLE 1
-- msg: START TRANSACTION
-- msg: ALTER TABLE 1
-- msg: ROLLBACK
-- error 428C9: cannot assign a value other than DEFAULT to column ID, which is GENERATED ALWAYS

-- # SET GENERATED needs F386 (Conformance Rules, 3), as well as T174 and F387
-- # for changing an identity column.
/* flags */
ALTER TABLE foo ALTER COLUMN id SET GENERATED BY DEFAULT;
-- flags: F386, F387, T174
-- error 42P01: no such table: ":memory:".PUBLIC.FOO

/* flags */
ALTER TABLE foo ALTER COLUMN id SET GENERATED ALWAYS RESTART;
-- flags: F386, F387, T174, T178
-- error 42P01: no such table: ":memory:".PUBLIC.FOO
